using System.Collections.Generic;
using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class ProductionLaneEnvironment:MonoBehaviour
{
readonly List<Material> mats=new();Transform root;
void Start(){root=new GameObject("DF_ProductionLanes").transform;root.SetParent(transform,false);BuildLane(16f);BuildLane(-16f);}
void BuildLane(float z){Material floor=Mat(Color.Lerp(StylizedArtDirection.ArenaStone,StylizedArtDirection.ArenaCenter,.45f),.28f,.26f),edge=Mat(Color.Lerp(StylizedArtDirection.ArenaStone,StylizedArtDirection.Ink,.25f),.55f,.32f),zero=Mat(Color.Lerp(StylizedArtDirection.ZeroMid,StylizedArtDirection.ArenaStone,.35f),.42f,.38f),lumen=Mat(Color.Lerp(StylizedArtDirection.LumenMid,StylizedArtDirection.ArenaStone,.35f),.42f,.38f),ze=Mat(StylizedArtDirection.ZeroEnergy,.08f,.58f,true),le=Mat(StylizedArtDirection.LumenEnergy,.08f,.58f,true);for(int i=0;i<14;i++){float x=-32.5f+i*5f;Panel("LanePanel",new Vector3(x,.055f,z),4.72f,4.25f,floor,i%2==0?.42f:.65f);}for(int side=-1;side<=1;side+=2){Material faction=side<0?zero:lumen,energy=side<0?ze:le;for(int i=0;i<6;i++){float x=side*(5f+i*5.25f);Panel("LaneShoulder",new Vector3(x,.075f,z+3.05f),4.7f,1.05f,faction,.38f);Panel("LaneShoulder",new Vector3(x,.075f,z-3.05f),4.7f,1.05f,faction,.38f);}Tube("LaneEnergy",new Vector3(side*3f,.115f,z+2.38f),new Vector3(side*34f,.115f,z+2.38f),.035f,energy);Tube("LaneEnergy",new Vector3(side*3f,.115f,z-2.38f),new Vector3(side*34f,.115f,z-2.38f),.035f,energy);for(int i=0;i<4;i++){float x=side*(9f+i*7.2f);ServiceEdge(new Vector3(x,.15f,z+4.05f),faction,energy);ServiceEdge(new Vector3(x,.15f,z-4.05f),faction,energy);}}}
void ServiceEdge(Vector3 p,Material metal,Material energy){GameObject d=ProductionMeshFactory.MeshObject("DF_LaneServiceNode",root,ProductionMeshFactory.Disc(.32f,.09f,20),metal);d.transform.localPosition=p;GameObject r=ProductionMeshFactory.MeshObject("DF_LaneServiceRing",root,ProductionMeshFactory.Ring(.24f,.025f,18,6),energy);r.transform.localPosition=p+Vector3.up*.12f;}
void Panel(string n,Vector3 p,float w,float d,Material mat,float bevel){Mesh m=PanelMesh(w,d,bevel);GameObject g=ProductionMeshFactory.MeshObject("DF_"+n,root,m,mat);g.transform.localPosition=p;}
Mesh PanelMesh(float w,float d,float bevel){float x=w*.5f,z=d*.5f,b=Mathf.Min(bevel,Mathf.Min(x,z)*.4f);Vector3[] v={new(-x+b,0,-z),new(x-b,0,-z),new(x,0,-z+b),new(x,0,z-b),new(x-b,0,z),new(-x+b,0,z),new(-x,0,z-b),new(-x,0,-z+b)};int[] t={0,1,2,0,2,3,0,3,4,0,4,5,0,5,6,0,6,7};Mesh m=new(){name="DF_ProductionFloorPanel",vertices=v,triangles=t};m.RecalculateNormals();m.RecalculateBounds();return m;}
void Tube(string n,Vector3 a,Vector3 b,float r,Material mat){ProductionMeshFactory.MeshObject("DF_"+n,root,ProductionMeshFactory.Tube(a,b,r,8),mat);}
Material Mat(Color c,float metallic,float smooth,bool emissive=false){Shader sh=Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard");Material m=new(sh);mats.Add(m);m.color=c;if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",c);if(m.HasProperty("_Metallic"))m.SetFloat("_Metallic",metallic);if(m.HasProperty("_Smoothness"))m.SetFloat("_Smoothness",smooth);if(emissive){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",c*1.35f);}return m;}
void OnDestroy(){foreach(Material m in mats)if(m!=null)Destroy(m);}
}
}